<x-app-layout><x-slot name="header"><div><h1 class="text-xl font-bold text-slate-900">Budget Prepare</h1><p class="mt-1 text-sm text-slate-500">Plan estimated costs for an event or campaign.</p></div></x-slot><section x-data="budgetForm()" class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div class="bg-[#1fafa0] px-6 py-4 text-sm font-semibold text-white">BUDGET PREPARE</div><form method="POST" action="{{route('budgets.store')}}" class="p-6">@csrf<div class="grid gap-6 md:grid-cols-2"><label class="text-sm font-semibold">Event<select name="promotion_event_id" x-model="eventId" @change="loadEventDate" required class="mt-2 block w-full rounded-md border-slate-300 py-2.5 text-sm"><option value="">Select event</option>@foreach($events as $event)<option value="{{$event->id}}">{{$event->title}}</option>@endforeach</select></label><label class="text-sm font-semibold">Event date<input type="date" x-model="eventDate" readonly class="mt-2 block w-full rounded-md border-slate-200 bg-slate-100 py-2.5 text-sm"></label><label class="text-sm font-semibold md:col-span-2">Remarks<textarea name="remarks" rows="2" class="mt-2 block w-full rounded-md border-slate-300 text-sm"></textarea></label></div><div class="mt-7 overflow-x-auto rounded-lg border border-sky-300"><table class="w-full min-w-[760px] text-sm"><thead class="bg-sky-500 text-white"><tr><th class="px-3 py-2 text-left">#</th><th class="px-3 py-2 text-left">Title</th><th class="px-3 py-2 text-left">Qty</th><th class="px-3 py-2 text-left">Unit Price</th><th class="px-3 py-2 text-left">Amount</th><th class="px-3 py-2 text-left">Note</th><th></th></tr></thead><tbody><template x-for="(item,index) in items" :key="index"><tr class="border-t"><td class="px-3 py-2" x-text="index+1"></td><td class="p-1"><input :name="`items[${index}][title]`" x-model="item.title" required class="w-full rounded border-slate-300"></td><td class="p-1"><input :name="`items[${index}][quantity]`" x-model.number="item.quantity" 